-- Phase 4 knowledge + razbory seed (KNOW-01..03, RAZB-01..04).
-- Idempotent: ON CONFLICT / WHERE NOT EXISTS; insert-only (no table wipes).
-- Shared VM (knowledge-db.ru): apply once via MCP/psql or supabase db push — never reset.
-- Embeddings: StubQueryEmbedder (sha256→1024-d) — must match application StubQueryEmbedder.

-- ─── Hybrid search RPC (SECURITY INVOKER; service_role adapter only) ───
create or replace function public.search_knowledge_chunks(
  query_embedding vector(1024),
  query_text text,
  role_filter text default null,
  result_limit int default 10,
  result_offset int default 0
)
returns table (
  material_id bigint,
  material_slug text,
  chunk_index int,
  snippet text,
  score double precision
)
language sql
stable
security invoker
set search_path = public
as $$
  with candidates as (
    select
      kc.material_id,
      m.slug as material_slug,
      kc.chunk_index,
      left(trim(kc.content_md), 180) as snippet,
      (
        0.7 * (1.0 - (kc.embedding <=> query_embedding))
        + 0.3 * coalesce(
          ts_rank_cd(kc.content_tsv, plainto_tsquery('simple', coalesce(query_text, ''))),
          0.0
        )
      )::double precision as score
    from knowledge_chunks kc
    join materials m on m.id = kc.material_id and m.status = 'ready'
    where (role_filter is null or role_filter = any (m.roles))
  ),
  best as (
    select distinct on (c.material_id)
      c.material_id,
      c.material_slug,
      c.chunk_index,
      c.snippet,
      c.score
    from candidates c
    where c.score > 0
    order by c.material_id, c.score desc
  )
  select b.material_id, b.material_slug, b.chunk_index, b.snippet, b.score
  from best b
  order by b.score desc
  limit greatest(result_limit, 0)
  offset greatest(result_offset, 0);
$$;

-- Revoke from PUBLIC / anon / authenticated; grant execute to service_role only (T-04-14).
revoke all on function public.search_knowledge_chunks(vector, text, text, int, int) from public;
revoke all on function public.search_knowledge_chunks(vector, text, text, int, int) from anon, authenticated;
grant execute on function public.search_knowledge_chunks(vector, text, text, int, int) to service_role;

